     TABLE(['موقع الورقة', 'متى؟', 'الهدف'], [['بداية الحصة', 'قبل الدرس', 'استدعاء ما سبق'], ['وسط الحصة', 'بعد الشرح مباشرة', 'تطبيق موجّه'], ['نهاية الحصة', 'آخر ١٠ دقائق', 'تقويم سريع'], ['واجب', 'بعد الحصة', 'ترسيخ مستقل']]),
